SELECT pi.id AS patient_id,
  pi.in_hospital_no AS in_hospital_no,
  pi.name AS patient_name,
  pi.gender AS gender,
  pi.depart_code AS depart_code,
  pi.in_depart_time AS in_depart_time,
  pi.out_depart_time AS out_depart_time,
  pi.bed_code AS bed_code,
  CAST(pi.diagnosis_content AS VARCHAR(2000)) AS diagnosis_content,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%ARDS%' OR d.diag_name LIKE '%急性呼吸窘迫%')) THEN 1 ELSE 0 END AS ards,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%ARDS%' OR d.diag_name LIKE '%急性呼吸窘迫%') AND d.diag_name LIKE '%轻度%') THEN 1 ELSE 0 END AS ards_mild,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%ARDS%' OR d.diag_name LIKE '%急性呼吸窘迫%') AND d.diag_name LIKE '%中度%') THEN 1 ELSE 0 END AS ards_moderate,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%ARDS%' OR d.diag_name LIKE '%急性呼吸窘迫%') AND d.diag_name LIKE '%重度%') THEN 1 ELSE 0 END AS ards_severe,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = '1' AND (pa.name LIKE '%气管插管%' OR pa.name LIKE '%机械通气%' OR pa.name LIKE '%呼吸机%')) THEN 1 ELSE 0 END AS intubated,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = '1' AND (pa.name LIKE '%无创%' OR pa.name LIKE '%BiPAP%' OR pa.name LIKE '%CPAP%' OR pa.name LIKE '%无创呼吸机%')) THEN 1 ELSE 0 END AS niv,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = '1' AND (pa.name LIKE '%高流量%' OR pa.name LIKE '%HFNC%' OR pa.name LIKE '%经鼻高流量%')) THEN 1 ELSE 0 END AS hfnc,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = '1' AND pa.name LIKE '%俯卧位%') OR EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_observe_module_item" i WHERE i.patient_id = pi.id AND i.del_flag = 0 AND i.item_name LIKE '%俯卧位%') THEN 1 ELSE 0 END AS prone,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = '1' AND pa.type_code = 'drug' AND (pa.name LIKE '%顺阿曲库铵%' OR pa.name LIKE '%阿曲库铵%' OR pa.name LIKE '%维库溴铵%' OR pa.name LIKE '%罗库溴铵%' OR pa.name LIKE '%哌库溴铵%')) THEN 1 ELSE 0 END AS muscle_relaxant,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_advice" pa WHERE pa.in_hospital_no = pi.in_hospital_no AND pa.del_flag = 0 AND pa.status = '1' AND (pa.name LIKE '%ECMO%' OR pa.name LIKE '%体外膜肺%')) THEN 1 ELSE 0 END AS ecmo,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND d.diag_name LIKE '%细菌性肺炎%') THEN 1 ELSE 0 END AS cause_bacterial_pneumonia,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%病毒性肺炎%' OR d.diag_name LIKE '%病毒肺炎%')) THEN 1 ELSE 0 END AS cause_viral_pneumonia,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%真菌性肺炎%' OR d.diag_name LIKE '%肺真菌%')) THEN 1 ELSE 0 END AS cause_fungal_pneumonia,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND d.diag_name LIKE '%吸入性肺炎%') THEN 1 ELSE 0 END AS cause_aspiration,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%肺挫伤%' OR d.diag_name LIKE '%肺挫裂伤%')) THEN 1 ELSE 0 END AS cause_contusion,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%脓毒症%' OR d.diag_name LIKE '%感染性休克%') AND d.diag_name NOT LIKE '%肺炎%') THEN 1 ELSE 0 END AS cause_extrapulmonary_infection,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%多发伤%' OR d.diag_name LIKE '%创伤性休克%')) THEN 1 ELSE 0 END AS cause_extrapulmonary_trauma,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%重症胰腺炎%' OR d.diag_name LIKE '%急性胰腺炎%')) THEN 1 ELSE 0 END AS cause_pancreatitis,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%大量输血%' OR d.diag_name LIKE '%输血相关%')) THEN 1 ELSE 0 END AS cause_massive_transfusion,
  CASE WHEN EXISTS (SELECT 1 FROM "zing_icu_db_prod"."patient_info_diagnosis" d WHERE d.patient_id = pi.id AND d.del_flag = 0 AND d.status = 1 AND (d.diag_name LIKE '%体外循环%' OR d.diag_name LIKE '%心脏术后%')) THEN 1 ELSE 0 END AS cause_cardiopulmonary_bypass,
  CASE WHEN pi.gender = '男' OR pi.gender = '1' OR pi.gender = 'M' THEN 1 ELSE 0 END AS sex_male,
  CASE WHEN REGEXP_LIKE(TRIM(pi.age), '^[0-9]{1,3}$') THEN CAST(TRIM(pi.age) AS INT) END AS age_num,
  (SELECT SUM(DATEDIFF(DAY, CASE WHEN pt.tube_set_start_time < TIMESTAMP '2026-09-01 00:00:00' THEN TIMESTAMP '2026-09-01 00:00:00' ELSE pt.tube_set_start_time END, CASE WHEN pt.tube_set_end_time IS NOT NULL AND pt.tube_set_end_time < TIMESTAMP '2026-10-01 00:00:00' THEN pt.tube_set_end_time WHEN pt.tube_take_away_time IS NOT NULL AND pt.tube_take_away_time < TIMESTAMP '2026-10-01 00:00:00' THEN pt.tube_take_away_time ELSE TIMESTAMP '2026-10-01 00:00:00' END)) FROM "zing_icu_db_prod"."patient_tube" pt WHERE pt.patient_id = pi.id AND pt.del_flag = 0 AND pt.tube_set_start_time < TIMESTAMP '2026-10-01 00:00:00' AND (pt.tube_set_end_time IS NULL OR pt.tube_set_end_time >= TIMESTAMP '2026-09-01 00:00:00') AND (pt.tube_code LIKE '%气管插管%' OR pt.tube_code LIKE '%气管切开%' OR pt.tube_name LIKE '%气管%')) AS mv_days,
  (SELECT SUM(DATEDIFF(MINUTE, pr.start_time, pr.end_time)) FROM "zing_doctor_db_prod"."patient_doc_prone_record" pr WHERE pr.patient_id = pi.id AND pr.status = 1 AND pr.record_status = 'submitted' AND pr.start_time < TIMESTAMP '2026-10-01 00:00:00' AND (pr.end_time IS NULL OR pr.end_time >= TIMESTAMP '2026-09-01 00:00:00')) AS prone_min,
  CASE WHEN pi.out_vest_type = 3 AND pi.out_depart_time >= TIMESTAMP '2026-09-01 00:00:00' AND pi.out_depart_time < TIMESTAMP '2026-10-01 00:00:00' THEN 1 ELSE 0 END AS died_in_period
FROM "zing_icu_db_prod"."patient_info" pi
WHERE (pi.del_flag = 0) AND (pi.in_depart_time IS NOT NULL) AND (pi.in_depart_time < TIMESTAMP '2026-10-01 00:00:00') AND ((pi.out_depart_time IS NULL OR pi.out_depart_time >= TIMESTAMP '2026-09-01 00:00:00'))